    if (!sp) {
      if (typeof ex.__runtime_init === "function") {
        ex.__runtime_init();
      }
      return;
    }
    ex.dream_heap_init();
    const tlsSize = ex.__tls_size?.value >>> 0;
    const tlsAlign = ex.__tls_align?.value >>> 0 || 1;
