const UNKNOWN_ZONE_OFFSET = -999999;

/**
 * Minutes *east* of UTC for the named IANA zone (e.g. "America/New_York") at `millis`, via the
 * standard `Intl.DateTimeFormat` "format then diff" trick: format `millis` as wall-clock parts in
 * `zoneName`, reinterpret those parts as UTC, and the difference from `millis` is the offset.
 * Returns `UNKNOWN_ZONE_OFFSET` if `zoneName` isn't a recognized IANA zone identifier.
 */
function zoneOffsetMinutes(zoneName, millis) {
  const ms = Number(millis);
  try {
    const dtf = new Intl.DateTimeFormat("en-US", {
      timeZone: zoneName,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
    });
    const parts = {};
    for (const p of dtf.formatToParts(ms)) parts[p.type] = p.value;
    const asUtc = Date.UTC(
      Number(parts.year),
      Number(parts.month) - 1,
      Number(parts.day),
      parts.hour === "24" ? 0 : Number(parts.hour),
      Number(parts.minute),
      Number(parts.second),
    );
    return Math.round((asUtc - ms) / 60000);
  } catch (_) {
    return UNKNOWN_ZONE_OFFSET;
  }
}

/** The host's configured IANA timezone name (e.g. "America/New_York"), or "" if unavailable. */
function localZoneName() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "";
  } catch (_) {
    return "";
  }
}

const cancellableDelay = Object.assign(ms => {
      let resolve;
      const pending = new Promise(done => { resolve = done; });
      const timer = setTimeout(resolve, Math.max(0, ms | 0));
      pending.cancel = () => { clearTimeout(timer); resolve(); };
      return pending;
    }, { cancelSynchronously: true });

function makeDatetimeTextHost() {
  return {
    unicodeNormalize: (text, form) => {
      const forms = ["NFC", "NFD", "NFKC", "NFKD"];
      const f = forms[form] || "NFC";
      return String(text).normalize(f);
    },
    unicodeToLower: (text) => String(text).toLocaleLowerCase(),
    unicodeToUpper: (text) => String(text).toLocaleUpperCase(),
    unicodeGraphemes: (text) => {
      const s = String(text);
      if (typeof Intl !== "undefined" && typeof Intl.Segmenter === "function") {
        const seg = new Intl.Segmenter(undefined, { granularity: "grapheme" });
        return Array.from(seg.segment(s), (part) => part.segment);
      }
      return Array.from(s);
    },
    dateNowMillis: () => BigInt(Date.now()),
    dateLocalOffsetMinutes: (millis) => -new Date(Number(millis)).getTimezoneOffset(),
    dateZoneOffsetMinutes: (zoneName, millis) => zoneOffsetMinutes(zoneName, millis),
    dateLocalZoneName: () => localZoneName(),
    timeNowNanos: () => {
      if (isNode) {
        return process.hrtime.bigint();
      } else {
        return BigInt(Math.floor(performance.now() * 1000000));
      }
    },
    delayMs: cancellableDelay,
  };
}

// ----- hosts.js -----
/**
 * Full built-in `Dream` host module (every optional chunk). Selective runtimes compose a subset
 * of these factories instead.
 */
function defaultDreamModule(getInstance) {
  return {
    ...makeJsHost(getInstance),
    ...makeCancellationHost(getInstance),
    ...makeFsHost(),
    ...makeNetHost(),
    ...makeCliHost(),
    ...makeCryptoHost(),
    ...makeDatetimeTextHost(),
    ...makeConsoleProcessHost(),
  };
}

// ----- workers.js -----
/**
 * Source of the worker bootstrap module. It imports this same `dream.js` (so the worker reuses
 * all the env/`Dream` import wiring, including nested workers) and, on `init`, instantiates the
 * same `.wasm` bytes importing the parent's shared `WebAssembly.Memory`. Thereafter each `msg` or
 * `dispatch` runs a `fun(string):string` body via `__workerInvoke` and posts the reply back.
 *
 * Browser workers use `self.onmessage` / `self.postMessage`; Node `worker_threads` workers use
 * `parentPort` instead — pass `node: true` for that dialect.
 */
function unpackWire(data) {
  if (data == null || data === "") {
    return "";
  }
  if (typeof data === "string") {
    return data;
  }
  const u =
    data instanceof Uint16Array
      ? data
      : new Uint16Array(data.buffer, data.byteOffset, Math.floor(data.byteLength / 2));
  if (u.length <= 8192) {
    return String.fromCharCode.apply(null, u);
  }
  let s = "";
  for (let i = 0; i < u.length; i += 8192) {
    s += String.fromCharCode.apply(null, u.subarray(i, i + 8192));
  }
  return s;
}

function packWire(s) {
  const n = s == null ? 0 : s.length;
  const u = new Uint16Array(n);
  for (let i = 0; i < n; i++) {
    u[i] = s.charCodeAt(i);
  }
  return u;
}

const WORKER_BOOT_UNPACK = `function unpackWire(data) {
  if (data == null || data === "") return "";
  if (typeof data === "string") return data;
  const u = data instanceof Uint16Array
    ? data
    : new Uint16Array(data.buffer, data.byteOffset, Math.floor(data.byteLength / 2));
  if (u.length <= 8192) return String.fromCharCode.apply(null, u);
  let s = "";
  for (let i = 0; i < u.length; i += 8192) s += String.fromCharCode.apply(null, u.subarray(i, i + 8192));
  return s;
}
function packWire(s) {
  const n = s == null ? 0 : s.length;
  const u = new Uint16Array(n);
  for (let i = 0; i < n; i++) u[i] = s.charCodeAt(i);
  return u;
}
`;

function workerBootSource(dreamUrl, { node = false } = {}) {
  if (node) {
    return `import { parentPort } from 'node:worker_threads';
import * as Dream from ${JSON.stringify(dreamUrl)};
${WORKER_BOOT_UNPACK}
let inst = null;
let chain = Promise.resolve();
parentPort.on('message', (m) => {
  chain = chain.then(async () => {
    if (m.t === 'init') {
      inst = await Dream.load(m.bytes, { abi: m.abi, memory: m.memory, stackGate: m.stackGate });
      parentPort.postMessage({ t: 'ready', stack: inst.workerStack || 0 });
    } else if (m.t === 'reset') {
      inst.__workerReset();
    } else if (m.t === 'msg' || m.t === 'dispatch') {
      const reply = await inst.__workerInvoke(m.fnIdx, m.env, unpackWire(m.data));
      parentPort.postMessage({ t: 'reply', data: packWire(reply), idle: inst._hostPending === 0 });
    } else if (m.t === 'term') {
      await inst.__workerClose();
      parentPort.postMessage({ t: 'closed' });
      parentPort.close();
    }
  });
});
`;
  }
  return `import * as Dream from ${JSON.stringify(dreamUrl)};
${WORKER_BOOT_UNPACK}
let inst = null;
let chain = Promise.resolve();
self.onmessage = (e) => {
  const m = e.data;
  chain = chain.then(async () => {
    if (m.t === 'init') {
      inst = await Dream.load(m.bytes, { abi: m.abi, memory: m.memory, stackGate: m.stackGate });
      self.postMessage({ t: 'ready', stack: inst.workerStack || 0 });
    } else if (m.t === 'reset') {
      inst.__workerReset();
    } else if (m.t === 'msg' || m.t === 'dispatch') {
      const reply = await inst.__workerInvoke(m.fnIdx, m.env, unpackWire(m.data));
      self.postMessage({ t: 'reply', data: packWire(reply), idle: inst._hostPending === 0 });
    } else if (m.t === 'term') {
      await inst.__workerClose();
      self.postMessage({ t: 'closed' });
      self.close();
    }
  });
};
`;
}

/**
 * Builds the `Dream`-module worker host functions (`workerSpawn`/`workerPost`/`workerRecv`/
 * `workerTerminate`/`workerPoolSpawn`/`workerPoolDispatch`) behind `system.task`'s `Task`/`TaskPool`.
 * Each worker is a real browser `Worker` or Node `worker_threads.Worker` running a fresh instance
 * of the same module, importing the parent's shared `WebAssembly.Memory`.
 * `workerRecv`/`workerPoolDispatch` are `extern async`, so they return Promises bridged into
 * Dream's scheduler.
 */
function makeWorkerModule(wasmBytes, abi, getSharedMemory, stackGate, getInstance) {
  const reg = new Map();
  const stopping = new Set();
  let nextId = 1;
  /** Lazily resolved Node `worker_threads.Worker` constructor (null until first Node spawn). */
  let NodeWorkerCtor = null;
  /**
   * Idle workers kept for the next session. Instantiating the module per Task dominated short
   * fan-outs, and each instance's stack stays carved out of shared memory until its worker has
   * stopped, so churning workers could exhaust the heap. A reused worker restarts its stack,
   * thread-locals, and private heap in place, so each session still starts as a fresh thread.
   */
  const idle = [];
  const IDLE_MAX = 64;

  // A slot is one worker; `slot.state` is the session it currently serves.
  const postJob = (state, job) => {
    const slot = state.slot;
    state.inflight++;
    if (slot.ready) slot.worker.postMessage(job);
    else slot.queued.push(job);
  };

  const onWorkerMessage = (slot, m) => {
    if (m.t === "ready") {
      slot.ready = true;
      slot.stack = Number(m.stack ?? 0);
      for (const q of slot.queued) slot.worker.postMessage(q);
      slot.queued = [];
    } else if (m.t === "closed") {
      slot.closed?.();
    } else if (m.t === "reply") {
      const state = slot.state;
      slot.idle = m.idle;
      if (!state) return;
      state.inflight--;
      const text = unpackWire(m.data);
      if (state.pending.length > 0) state.pending.shift()(text);
      else state.replies.push(text);
    }
  };

  const attachHandlers = (worker, slot) => {
    // Browser: `onmessage` event with `e.data`. Node worker_threads: `message` event with data directly.
    if (typeof worker.on === "function" && isNode) {
      worker.on("message", (m) => onWorkerMessage(slot, m));
    } else {
      worker.onmessage = (e) => onWorkerMessage(slot, e.data);
    }
  };

  const publish = (ptr) => {
    const n = Number(ptr ?? 0);
    if (!n) return;
    if (typeof getInstance !== "function") {
      throw new Error("dream_publish: Wasm instance is not ready");
    }
    const inst = getInstance();
    const pub = inst && inst.exports && inst.exports.dream_publish;
    if (typeof pub !== "function") {
      throw new Error("dream_publish export is missing");
    }
    pub(n);
  };

  const startWorker = (state) => {
    const slot = {
      worker: null,
      state,
      ready: false,
      queued: [],
      blobUrl: null,
      stack: 0,
      idle: true,
    };

    const finishSpawn = (worker) => {
      slot.worker = worker;
      attachHandlers(worker, slot);
      worker.postMessage({
        t: "init",
        bytes: wasmBytes,
        abi,
        memory: getSharedMemory(),
        stackGate,
      });
    };

    if (isNode) {
      // Spawn synchronously once the ctor is cached; first call kicks off an async import and
      // queues the init until it resolves (postJob already buffers until `ready`).
      const startNode = (NodeWorker) => {
        const worker = new NodeWorker(workerBootSource(import.meta.url, { node: true }), {
          eval: true,
        });
        finishSpawn(worker);
      };
      if (NodeWorkerCtor) {
        startNode(NodeWorkerCtor);
      } else {
        // Synchronous-looking spawn from Dream's POV: register the id immediately; jobs queue
        // until the worker posts `ready`. The dynamic import of worker_threads is one-shot.
        import("node:worker_threads").then(({ Worker }) => {
          NodeWorkerCtor = Worker;
          startNode(Worker);
        });
      }
    } else if (typeof Worker !== "undefined") {
      const url = URL.createObjectURL(
        new Blob([workerBootSource(import.meta.url)], { type: "text/javascript" }),
      );
      slot.blobUrl = url;
      finishSpawn(new Worker(url, { type: "module" }));
    } else {
      throw new Error(
        "Task needs a thread runtime (browser Worker or Node worker_threads); neither is available in this environment",
      );
    }
    return slot;
  };

  const spawnWorker = (fnIndex, env) => {
    publish(env);
    const state = {
      slot: null,
      fnIndex: Number(fnIndex ?? 0),
      env: Number(env ?? 0),
      pending: [],
      replies: [],
      inflight: 0,
    };
    const reused = idle.pop();
    if (reused) {
      reused.state = state;
      state.slot = reused;
      if (typeof reused.worker.ref === "function") reused.worker.ref();
      reused.worker.postMessage({ t: "reset" });
    } else {
      state.slot = startWorker(state);
    }
    const id = nextId++;
    reg.set(id, state);
    return id;
  };

  return {
    // `body` arrives marshaled as a JS callable wrapping the Dream funcref; recover its raw funcidx
    // and closure-env word (0 for a non-capturing body).
    workerSpawn: (body, env) =>
      spawnWorker(body && body.__dreamFuncIndex != null ? body.__dreamFuncIndex : body, env),
    workerPoolSpawn: () => spawnWorker(0, 0),
    workerPost: (id, msg) => {
      const s = reg.get(id);
      if (!s) return;
      postJob(s, { t: "msg", fnIdx: s.fnIndex, env: s.env, data: packWire(msg) });
    },
    workerPoolDispatch: (id, fnIndex, env, msg) =>
      new Promise((resolve) => {
        const s = reg.get(id);
        if (!s) return resolve("");
        publish(env);
        s.pending.push(resolve);
        postJob(s, { t: "dispatch", fnIdx: fnIndex, env, data: packWire(msg) });
      }),
    // extern async: resolve with the next reply (or "" if the worker is gone).
    workerRecv: (id) =>
      new Promise((resolve) => {
        const s = reg.get(id);
        if (!s) return resolve("");
        if (s.replies.length > 0) resolve(s.replies.shift());
        else s.pending.push(resolve);
      }),
    // JS termination never blocks the caller, so there is nothing to overlap.
    __drainWorkers: async () => {
      while (stopping.size) await Promise.all([...stopping]);
    },
    workerShutdown: () => {},
    workerTerminate: (id) => {
      const s = reg.get(id);
      if (!s) return;
      reg.delete(id);
      for (const p of s.pending) p("");
      const slot = s.slot;
      // A worker mid-job, or whose last job left host calls running, cannot be handed on: they
      // would settle into the next session's thread.
      if (slot.worker && slot.ready && slot.idle && s.inflight === 0 && idle.length < IDLE_MAX) {
        slot.state = null;
        // An idle Node worker must not keep the process alive.
        if (typeof slot.worker.unref === "function") slot.worker.unref();
        idle.push(slot);
        return;
      }
      const releaseStack = () => {
        if (slot.stack && typeof getInstance === "function") {
          getInstance().exports.dream_wasm_raw_free(slot.stack);
        }
      };
      if (slot.worker) {
        const stopped = new Promise((resolve) => {
          const terminate = () => {
            const result = slot.worker.terminate();
            if (result && typeof result.then === "function") {
              result.then(() => { releaseStack(); resolve(); }, resolve);
            } else { releaseStack(); resolve(); }
          };
          // Finished bodies retire gracefully; a busy body still needs immediate termination.
          if (slot.ready && s.inflight === 0) {
            slot.closed = terminate;
            slot.worker.postMessage({ t: "term" });
          } else { terminate(); }
        });
        stopping.add(stopped);
        stopped.then(() => stopping.delete(stopped));
      }
      if (slot.blobUrl) {
        try {
          URL.revokeObjectURL(slot.blobUrl);
        } catch (_) {
          /* ignore */
        }
      }
    },
  };
}

// ----- urls.js -----
/** WASM custom-section name written by `embed_abi_in_wasm` (`src/driver/abi.rs`). */
const ABI_CUSTOM_SECTION = "dream-abi";

/**
 * ABI JSON baked into the module. `run("./mod.wasm")` should not need a sibling fetch.
 */
function readEmbeddedAbi(wasmModule) {
  if (typeof WebAssembly.Module.customSections !== "function") return null;
  const secs = WebAssembly.Module.customSections(wasmModule, ABI_CUSTOM_SECTION);
  if (!secs.length) return null;
  return JSON.parse(new TextDecoder("utf-8").decode(secs[0]));
}

/**
 * Swap a Dream artifact extension (`.wasm` / `.abi.json`), keeping `?query` / `#hash`.
 * Fallback when an older `.wasm` has no embedded ABI section.
 */
function replaceArtifactExt(source, ext) {
  if (typeof source !== "string") return undefined;
  const q = source.search(/[?#]/);
  const path = q < 0 ? source : source.slice(0, q);
  const extra = q < 0 ? "" : source.slice(q);
  const stem = path.endsWith(".abi.json")
    ? path.slice(0, -9)
    : path.endsWith(".wasm")
      ? path.slice(0, -5)
      : null;
  if (stem == null) return undefined;
  return stem + ext + extra;
}

// ----- load.js -----
const FALLBACK_INITIAL_MEMORY_PAGES = 64;
const FALLBACK_MAX_MEMORY_PAGES = 65536;

async function fetchBytes(source) {
  if (source instanceof ArrayBuffer) return new Uint8Array(source);
  if (source instanceof Uint8Array) return source;
  if (!isNode && typeof fetch === "function") {
    const res = await fetch(source);
    if (!res.ok) throw new Error(`failed to fetch ${source}: ${res.status}`);
    return new Uint8Array(await res.arrayBuffer());
  }
  const { readFile } = await import("node:fs/promises");
  return new Uint8Array(await readFile(source));
}

async function loadAbi(abi) {
  if (!abi) return null;
  if (typeof abi === "object" && abi.externs) return abi;
  const bytes = await fetchBytes(abi);
  return JSON.parse(new TextDecoder("utf-8").decode(bytes));
}

async function resolveAbi(wasmModule, source, options) {
  if (options.abi && typeof options.abi === "object" && options.abi.externs) {
    return options.abi;
  }
  const embedded = readEmbeddedAbi(wasmModule);
  if (embedded) return embedded;
  const url =
    typeof options.abi === "string" ? options.abi : replaceArtifactExt(source, ".abi.json");
  return loadAbi(url);
}

/**
 * Scans the wasm binary's import section for an `env`/`memory` import and reads its limits
 * flags (bit 1 = shared). Engines do not reliably expose `.type.shared` on
 * `WebAssembly.Module.imports()` entries, so this is the dependable signal.
 */
function memoryImportIsShared(bytes) {
  const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let pos = 8; // magic + version
  const leb = () => {
    let result = 0;
    let shift = 0;
    for (;;) {
      const b = u8[pos++];
      result += (b & 0x7f) * Math.pow(2, shift);
      if (!(b & 0x80)) return result;
      shift += 7;
    }
  };
  const limits = () => {
    const flags = leb();
    leb(); // min
    if (flags & 0x01) leb(); // max
    return flags;
  };
  while (pos < u8.length) {
    const id = u8[pos++];
    const size = leb();
    if (id !== 2) {
      pos += size; // not the import section
      continue;
    }
    const end = pos + size;
    const count = leb();
    for (let i = 0; i < count && pos < end; i++) {
      // NB: `pos += leb()` would read `pos` before `leb()` runs — but leb() mutates pos
      // through the closure, so the skip would land one byte short. Stage lengths first.
      const moduleLen = leb();
      pos += moduleLen;
      const nameLen = leb();
      pos += nameLen;
      const kind = u8[pos++];
      if (kind === 2) {
        return (limits() & 0x02) !== 0; // shared flag
      } else if (kind === 0) {
        leb(); // func: type index
      } else if (kind === 1) {
        pos += 1; // table: element type
        limits();
      } else if (kind === 3) {
        pos += 2; // global: valtype + mutability
      } else {
        break; // unknown kind — stop scanning rather than desync
      }
    }
    return false;
  }
  return false;
}

function moduleWantsSharedMemory(wasmModule, desc) {
  if (desc && desc.shared) {
    return true;
  }
  // `Module.imports()[].type` is missing in some browsers. Shared-memory modules (`Task`)
  // still import the worker hosts; use either signal.
  return WebAssembly.Module.imports(wasmModule).some(
    (i) =>
      (i.kind === "memory" && i.module === "env" && i.name === "memory" && i.type && i.type.shared) ||
      (i.kind === "function" &&
        i.module === "Dream" &&
        (i.name === "workerSpawn" ||
          i.name === "workerPost" ||
          i.name === "workerRecv" ||
          i.name === "workerShutdown" ||
          i.name === "workerTerminate" ||
          i.name === "workerPoolSpawn" ||
          i.name === "workerPoolDispatch")),
  );
}

function memoryIsShared(memory) {
  return (
    typeof SharedArrayBuffer !== "undefined" &&
    memory.buffer instanceof SharedArrayBuffer
  );
}

function makeLinearMemory(wasmModule, wasmBytes) {
  const memoryImport = WebAssembly.Module.imports(wasmModule).find(
    (i) => i.module === "env" && i.name === "memory" && i.kind === "memory",
  );
  const desc = memoryImport && memoryImport.type;
  return new WebAssembly.Memory({
    initial: desc && desc.minimum != null ? desc.minimum : FALLBACK_INITIAL_MEMORY_PAGES,
    maximum: desc && desc.maximum != null ? desc.maximum : FALLBACK_MAX_MEMORY_PAGES,
    shared:
      moduleWantsSharedMemory(wasmModule, desc) || memoryImportIsShared(wasmBytes),
  });
}

/**
 * Loads and instantiates a Dream module.
 *
 * @param {string|ArrayBuffer|Uint8Array} source - URL/path to `.wasm`, or raw bytes.
 * @param {object} [options]
 * @param {object} [options.imports] - JS implementations keyed by extern function name.
 * @param {string|object} [options.abi] - URL/path to (or parsed) `.abi.json` for auto-marshaling.
 * @param {function} [options.stdout] - Custom output sink for print builtins.
 * @param {function} [options.dreamHosts] - Optional host-factory composer; defaults to full module.
 * @returns {Promise<DreamInstance>}
 */
async function load(source, options = {}) {
  const wasmBytes = await fetchBytes(source);
  const wasmModule = await WebAssembly.compile(wasmBytes);
  const abi = await resolveAbi(wasmModule, source, options);

  if (isNode && !options.__skipNodePreload) {
    try {
      const fs = await import("node:fs");
      setNodeFs(fs);
    } catch (_) { /* leave unavailable */ }
    try {
      const crypto = await import("node:crypto");
      setNodeCrypto(crypto);
    } catch (_) { /* leave unavailable */ }
    try {
      const childProcess = await import("node:child_process");
      setNodeChildProcess(childProcess);
    } catch (_) { /* leave unavailable */ }
    try {
      const net = await import("node:net");
      setNodeNet(net);
    } catch (_) { /* leave unavailable */ }
  }

  let instance = null;
  const getInstance = () => {
    if (!instance) throw new Error("instance not ready");
    return instance;
  };

  const importObject = { env: defaultEnv(getInstance, options) };
  const sharedMemory = options.memory ?? makeLinearMemory(wasmModule, wasmBytes);
  importObject.env.memory = sharedMemory;
  const stackGate =
    options.stackGate ??
    (memoryIsShared(sharedMemory) ? new Int32Array(new SharedArrayBuffer(4)) : null);

  const userImports = options.imports || {};
  const sigByName = new Map();
  if (abi) for (const e of abi.externs) sigByName.set(e.name, e);

  const composeHosts = options.dreamHosts || defaultDreamModule;
  // Selective runtimes omit chunk files whose hosts are unused; `typeof` guards keep
  // those references safe when the defining file was not included.
  const builtinDream = {
    ...composeHosts(getInstance),
    ...(typeof makeWorkerModule === "function"
      ? makeWorkerModule(wasmBytes, abi, () => sharedMemory, stackGate, getInstance)
      : {}),
  };
  const wrapFor = (fn, sig) => {
    return sig && sig.async ? wrapAsyncImport(getInstance, fn, sig) : wrapImport(getInstance, fn, sig);
  };

  for (const name of Object.keys(userImports)) {
    const sig = sigByName.get(name);
    const module = sig ? sig.module : "env";
    const field = sig ? sig.field : name;
    (importObject[module] ||= {})[field] = wrapFor(userImports[name], sig);
  }

  if (abi) {
    for (const e of abi.externs) {
      const bucket = (importObject[e.module] ||= {});
      if (bucket[e.field]) continue;
      const resolved = (e.module === "Dream" && builtinDream[e.field])
        ? builtinDream[e.field]
        : resolveGlobal(e.module, e.field);
      bucket[e.field] = resolved
        ? wrapFor(resolved, e)
        : () => {
            throw new Error(`no JS implementation for extern '${e.name}' (${e.module}.${e.field})`);
          };
    }
  }

  // Compiler-emitted imports (e.g. `jsRetain` / `jsRelease`) appear in the WASM module but are not
  // listed in `.abi.json` — bind any still-missing Dream functions from the host factory.
  // WASM passes a handle id; marshal `js` so the host sees the registered value.
  const jsRcSig = { params: ["js"], result: "void" };
  for (const imp of WebAssembly.Module.imports(wasmModule)) {
    if (imp.kind !== "function" || imp.module !== "Dream") continue;
    const bucket = (importObject.Dream ||= {});
    if (bucket[imp.name]) continue;
    const resolved = builtinDream[imp.name];
    const rcSig = (imp.name === "jsRetain" || imp.name === "jsRelease") ? jsRcSig : null;
    bucket[imp.name] = resolved
      ? wrapFor(resolved, rcSig)
      : () => {
          throw new Error(`no JS implementation for Dream.${imp.name}`);
        };
  }

  await withBootstrapLock(stackGate, async () => {
    const inst = await WebAssembly.instantiate(wasmModule, importObject);
    instance = new DreamInstance(inst);
    if (builtinDream.__drainWorkers) instance._drainWorkers = builtinDream.__drainWorkers;
    if (stackGate || options.memory) {
      instance.__attachGuestStack(0);
    } else if (typeof inst.exports.__runtime_init === "function") {
      inst.exports.__runtime_init();
    }
    return inst;
  });
  return instance;
}

async function withBootstrapLock(gate, fn) {
  if (!gate) {
    return fn();
  }
  for (;;) {
    if (Atomics.compareExchange(gate, 0, 0, 1) === 0) {
      break;
    }
    if (typeof Atomics.waitAsync === "function") {
      await Atomics.waitAsync(gate, 0, 1, 50).value;
    } else {
      await new Promise((r) => setTimeout(r, 0));
    }
  }
  try {
    return await fn();
  } finally {
    Atomics.store(gate, 0, 0);
    Atomics.notify(gate, 0);
  }
}

/**
 * load a module and immediately invoke its `main`.
 *
 * A non-zero exit status (`main(): int`, or a failing `Result` main) is surfaced on Node as
 * `process.exitCode`, and always as `mod.exitCode`.
 *
 * With `options.leakReport`, a debug build's live heap-object count is printed to stderr after
 * globals drop, in the `[dream] leak check: live=N` form native debug builds print at exit.
 *
 * @returns {Promise<DreamInstance>} the loaded instance (after `main` has run).
 */
async function run(source, options = {}) {
  const mod = await load(source, options);
  const code = await mod.run();
  if (options.leakReport && typeof mod.exports.__dream_leak_live === "function") {
    console.error(`[dream] leak check: live=${mod.exports.__dream_leak_live()}`);
  }
  if (code && typeof process !== "undefined") {
    process.exitCode = code;
  }
  return mod;
}

const __default_export__ = { load, run, DreamInstance, TAGS, HEAP_HEADER_SIZE };

export { load, run, DreamInstance, TAGS, HEAP_HEADER_SIZE };
export default { load, run, DreamInstance, TAGS, HEAP_HEADER_SIZE };
